let tokens = 0;
let isRefilling = false;

function allow() {
  if (tokens > 0) {
    tokens--;
    return true;
  }
  return false;
}

setInterval(() => {
  if (!isRefilling) {
    isRefilling = true;
    tokens = 5;
    isRefilling = false;
  }
}, 1000);
